rollback.sql:
DO $$
BEGIN
    LOCK TABLE modeling_model_release_candidate_entry
        IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (
        SELECT 1
          FROM modeling_model_release_candidate_entry
         WHERE (
                implementation_revision IS NULL
                AND active_claim_key IS NOT NULL
            )
            OR (
                implementation_revision IS NOT NULL
                AND status IN ('REJECTED', 'ROLLED_BACK', 'STALE')
                AND active_claim_key IS NULL
            )
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_RELEASE_CANDIDATE_CLAIM_TRANSFER_DATA_EXISTS';
    END IF;
END $$;
